// ============================================================
// Splitbill 多語系（中／日／英）核心模組。
//
// 純 plain script（不是 ES module），跟 currencies.js/theme.js 一樣直接
// 用 <script> 標籤在每個頁面的 <head> 載入，載入順序要排在所有會用到
// t()/applyI18n() 的其他 script 之前。
//
// 用法：
//   - 靜態文字：<span data-i18n="key">預設中文（給沒 JS 時的 fallback）</span>
//   - placeholder：<input data-i18n-placeholder="key" placeholder="...">
//   - title/aria-label：<button data-i18n-title="key" title="...">
//   - 含簡單內嵌標籤（例如 <b>）的整段文字：<p data-i18n-html="key">...</p>
//   - JS 動態文字（例如 msg.textContent = "..."）：一律改成
//     msg.textContent = t("key")，不能只靠 data-i18n（那個只在
//     applyI18n() 執行的當下套用一次，之後 JS 自己覆蓋掉的文字不會
//     自動翻譯）。
//
// 新增字串的流程：先在 I18N["zh-Hant"] 裡加一個 key，再把同一個 key
// 加進 I18N["ja"]／I18N["en"]，三邊 key 要完全對齊——currentLang 找不到
// 某個 key 時會自動 fallback 回 zh-Hant，但長期放著不翻不管理會很亂。
// ============================================================

const SUPPORTED_LANGS = ["zh-Hant", "ja", "en"];
