    "settings.basicInfoTitle": "基本情報",
    "settings.avatarLabel": "プロフィール画像",
    "settings.avatarPreviewTitle": "タップして拡大表示",
    "settings.avatarViewPhoto": "プロフィール画像を見る",
    "settings.avatarChangePhoto": "📷 画像を変更",
    "settings.avatarRemove": "✕ 削除",
    "settings.avatarHint": "アバターまたは 🔍 拡大アイコンをタップして写真を見る。カメラ・アルバムからのトリミングに対応",
    "settings.usernameInfo": "サイト全体で一意で、他の人と重複できません。ログインページでこの名前を直接入力してログインでき、メールを覚える必要はありません。変更すると、すべてのグループのデフォルト表示名に同期反映されます——ただし個別にニックネームを設定しているグループはそちらが優先され、影響を受けません。漢字・英数字・アンダースコアで2〜20文字。",
